using Microsoft.EntityFrameworkCore;
using Microsoft.Extensions.Logging;

namespace MyApp;

/// <summary>
/// Entity Framework Core の DbContext。
///
/// 定型的な設定は自動生成された <see cref="AutoGeneratedDbContext"/> でなされている。
/// こちらでは必要に応じて拡張やオーバーライドを行う。
/// </summary>
public partial class OverridedDbContext : AutoGeneratedDbContext {
    public OverridedDbContext(
        DbContextOptions<OverridedDbContext> options,
        ILogger<OverridedDbContext> logger,
        IAuditInfo auditInfo,
        IDisplayMessageFactory messageFactory) : base(options, auditInfo, messageFactory) {
        _logger = logger;
    }

    /// <summary>SQLや保存処理のログ出力用</summary>
    private readonly ILogger<OverridedDbContext> _logger;

    protected override void OnConfiguring(DbContextOptionsBuilder optionsBuilder) {
        // EFCore が標準で出力するログのうち Information 以上のものを標準のデバッグログとして出力する
        // （EFCore の Information はSQLなどで、 Debug はコネクションの接続や解放などが含まれる）。
        // EFCore 側のログ（"Microsoft.EntityFrameworkCore" カテゴリで出力される）と二重で出力されるので、
        // 必要に応じて EFCore 側のログが出力されないように調整などすること。
        optionsBuilder.LogTo(
            sql => _logger.LogDebug(sql),
            LogLevel.Information,
            Microsoft.EntityFrameworkCore.Diagnostics.DbContextLoggerOptions.SingleLine);

        // Error レベルのログは運用担当者への通知の対象となる。
        // 一意制約違反など通知が不要なDBエラーも EFCore は既定で Error レベルで出力してしまうので引き下げ、
        // 通知が必要か否かはエラーの内容を判断できる保存処理やアプリケーションの例外処理に任せる。
        optionsBuilder.ConfigureWarnings(warnings => warnings.Log(
            (Microsoft.EntityFrameworkCore.Diagnostics.RelationalEventId.CommandError, LogLevel.Warning),
            (Microsoft.EntityFrameworkCore.Diagnostics.CoreEventId.SaveChangesFailed, LogLevel.Warning)));
    }
}
